/** of those state-change happens (this is done in core module) */
export class rlDrawCall {
  /** SIZE member. */
  static readonly SIZE = 16;
  #buffer: Uint8Array<ArrayBuffer>;
  #view: DataView;

  /** constructor member. */
  constructor(buffer: Uint8Array<ArrayBuffer>);
  /** constructor member. */
  constructor(
    options: Partial<
      {
        mode: number;
        vertexCount: number;
        vertexAlignment: number;
        textureId: number;
      }
    >,
  );
  /** constructor member. */
  constructor(
    mode: number,
    vertexCount: number,
    vertexAlignment: number,
    textureId: number,
  );
  /** constructor member. */
  constructor(
    arg0:
      | Uint8Array<ArrayBuffer>
      | Partial<
        {
          mode: number;
          vertexCount: number;
          vertexAlignment: number;
          textureId: number;
        }
      >
      | number,
    ...rest: unknown[]
  ) {
    if (arg0 instanceof Uint8Array) {
      this.#buffer = arg0;
      this.#view = new DataView(
        this.#buffer.buffer,
        this.#buffer.byteOffset,
        this.#buffer.byteLength,
      );
      return;
    }
    this.#buffer = new Uint8Array(new ArrayBuffer(rlDrawCall.SIZE));
    this.#view = new DataView(
      this.#buffer.buffer,
      this.#buffer.byteOffset,
      this.#buffer.byteLength,
    );
    if (arg0 && typeof arg0 === "object" && !("buffer" in (arg0 as object))) {
      if ((arg0 as any).mode !== undefined) this.mode = (arg0 as any).mode;
      if ((arg0 as any).vertexCount !== undefined) {
        this.vertexCount = (arg0 as any).vertexCount;
      }
      if ((arg0 as any).vertexAlignment !== undefined) {
        this.vertexAlignment = (arg0 as any).vertexAlignment;
      }
      if ((arg0 as any).textureId !== undefined) {
        this.textureId = (arg0 as any).textureId;
      }
      return;
    }
    const args = [arg0, ...rest];
    if (args[0] !== undefined) this.mode = args[0] as any;
    if (args[1] !== undefined) this.vertexCount = args[1] as any;
    if (args[2] !== undefined) this.vertexAlignment = args[2] as any;
    if (args[3] !== undefined) this.textureId = args[3] as any;
  }

  /** fromBuffer member. */
  static fromBuffer(buffer: ArrayBufferLike, byteOffset = 0): rlDrawCall {
    return new rlDrawCall(
      new Uint8Array(buffer as ArrayBuffer, byteOffset, rlDrawCall.SIZE),
    );
  }

  /** buffer member. */
  get buffer(): Uint8Array<ArrayBuffer> {
    return this.#buffer;
  }

  /** mode member. */
  get mode(): number {
    return this.#view.getInt32(0, littleEndian) as number;
  }

  /** mode member. */
  set mode(value: number) {
    this.#view.setInt32(0, value as any, littleEndian);
  }

  /** vertexCount member. */
  get vertexCount(): number {
    return this.#view.getInt32(4, littleEndian) as number;
  }

  /** vertexCount member. */
  set vertexCount(value: number) {
    this.#view.setInt32(4, value as any, littleEndian);
  }

  /** vertexAlignment member. */
  get vertexAlignment(): number {
    return this.#view.getInt32(8, littleEndian) as number;
  }

  /** vertexAlignment member. */
  set vertexAlignment(value: number) {
    this.#view.setInt32(8, value as any, littleEndian);
  }

  /** textureId member. */
  get textureId(): number {
    return this.#view.getUint32(12, littleEndian) as number;
  }

  /** textureId member. */
  set textureId(value: number) {
    this.#view.setUint32(12, value as any, littleEndian);
  }
}

